import json

data = json.load(open('/app/resources/treasury_bulletin_2004_03.json'))
elements = data['document']['elements']

# Look at all tables that have '2000' and '2002' in them, specifically for China/Taiwan data
for i, el in enumerate(elements):
    if el.get('type') == 'table':
        content = str(el.get('content', ''))
        # Check if it has multiple years and China/Taiwan data
        if '<td>2000</td>' in content and '<td>2002' in content:
            if 'Mainland' in content or 'China:' in content:
                # Check if it's about liabilities
                print(f'Element {i}:')
                # Print just the Mainland and Taiwan rows
                lines = content.split('<tr>')
                for line in lines:
                    if 'Mainland' in line or '<td>Taiwan</td>' in line:
                        print(line[:300])
                print()
