import json

data = json.load(open('/app/resources/treasury_bulletin_2004_03.json'))
elements = data['document']['elements']

# Look for any section headers mentioning IFS (International Financial Statistics)
for i, el in enumerate(elements):
    if el.get('type') == 'section_header':
        content = str(el.get('content', ''))
        if 'IFS' in content or 'International Financial' in content:
            print(f"Element {i}: {content}")

# Also look for any table with title that includes "Selected U.S. Liabilities"
for i, el in enumerate(elements):
    if el.get('type') == 'table':
        content = str(el.get('content', ''))
        # Check if it's the IFS-2 table
        if 'IFS-2' in content:
            print(f"\nElement {i} has IFS-2")
            # Check what's nearby
            for j in range(max(0, i-3), min(len(elements), i+3)):
                e = elements[j]
                print(f"  {j}: {e.get('type')} - {str(e.get('content', ''))[:100]}")
